"""The ``pennywise`` command line."""

import argparse
import csv
import io
import json
import sys

from .ledger import (
    Entry,
    ParseError,
    check_amount,
    check_category,
    check_date,
    format_amount,
    format_entry,
    parse,
)
from .reports import balance, by_category, by_month, filter_entries


class _Fail(Exception):
    def __init__(self, code, message):
        super().__init__(message)
        self.code = code
        self.message = message


def _date_arg(text):
    try:
        return check_date(text)
    except ValueError as exc:
        raise argparse.ArgumentTypeError(str(exc)) from None


def _read_text(path):
    if path == "-":
        try:
            return sys.stdin.read()
        except (OSError, ValueError) as exc:
            raise _Fail(2, "cannot read standard input: {}".format(exc)) from None
    try:
        with open(path, encoding="utf-8", newline="") as handle:
            return handle.read()
    except OSError as exc:
        raise _Fail(2, "cannot read {}: {}".format(path, exc.strerror or exc)) from None
    except ValueError as exc:
        raise _Fail(2, "cannot read {}: {}".format(path, exc)) from None


def _load(path):
    try:
        return parse(_read_text(path))
    except ParseError as exc:
        raise _Fail(1, str(exc)) from None


def _sorted_entries(entries):
    return sorted(entries, key=lambda e: e.date)


def _json(value):
    return json.dumps(value) + "\n"


def _lines(lines):
    return "".join(line + "\n" for line in lines)


def _cmd_balance(args):
    total = format_amount(balance(_load(args.file)))
    if args.json:
        return _json({"balance": total})
    return total + "\n"


def _cmd_summary(args):
    entries = _load(args.file)
    totals = by_month(entries) if args.by == "month" else by_category(entries)
    shown = {name: format_amount(totals[name]) for name in sorted(totals)}
    if args.json:
        return _json(shown)
    return _lines("{}  {}".format(name, total) for name, total in shown.items())


def _selected(args):
    entries = filter_entries(
        _load(args.file),
        category=getattr(args, "category", None),
        since=getattr(args, "since", None),
        until=getattr(args, "until", None),
    )
    return _sorted_entries(entries)


def _cmd_list(args):
    entries = _selected(args)
    if args.json:
        return _json(
            [
                {
                    "date": e.date.isoformat(),
                    "category": e.category,
                    "amount": format_amount(e.amount),
                    "note": e.note,
                }
                for e in entries
            ]
        )
    return _lines(format_entry(e) for e in entries)


def _cmd_export(args):
    out = io.StringIO()
    writer = csv.writer(out, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in _selected(args):
        writer.writerow([e.date.isoformat(), e.category, format_amount(e.amount), e.note])
    return out.getvalue()


def _line_count(text):
    if not text:
        return 0
    return text.count("\n") + (0 if text.endswith("\n") else 1)


def _cmd_add(args):
    if args.file == "-":
        raise _Fail(2, "add does not accept '-' (give a file name)")
    try:
        with open(args.file, encoding="utf-8", newline="") as handle:
            existing = handle.read()
    except FileNotFoundError:
        existing = ""
    except OSError as exc:
        raise _Fail(2, "cannot read {}: {}".format(args.file, exc.strerror or exc)) from None
    except ValueError as exc:
        raise _Fail(2, "cannot read {}: {}".format(args.file, exc)) from None

    number = _line_count(existing) + 1
    note = (args.note or "").strip()
    try:
        date = check_date(args.date)
        category = check_category(args.category)
        amount = check_amount(args.amount)
        if "\n" in note or "\r" in note:
            raise ValueError("invalid note (must not contain a newline)")
    except ValueError as exc:
        raise _Fail(1, "line {}: {}".format(number, exc)) from None

    line = format_entry(Entry(date, category, amount, note))
    prefix = "\n" if existing and not existing.endswith("\n") else ""
    try:
        with open(args.file, "a", encoding="utf-8", newline="") as handle:
            handle.write(prefix + line + "\n")
    except OSError as exc:
        raise _Fail(2, "cannot write {}: {}".format(args.file, exc.strerror or exc)) from None
    return line + "\n"


def _build_parser():
    parser = argparse.ArgumentParser(
        prog="pennywise", description="Tell me where the household money went."
    )
    sub = parser.add_subparsers(dest="command", metavar="COMMAND")
    sub.required = True

    def reader(name, help_text):
        p = sub.add_parser(name, help=help_text, description=help_text)
        p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
        return p

    p = reader("balance", "print the total of all amounts")
    p.add_argument("--json", action="store_true", help="print JSON")
    p.set_defaults(func=_cmd_balance)

    p = reader("summary", "print totals per category or month")
    p.add_argument("--by", choices=["category", "month"], default="category")
    p.add_argument("--json", action="store_true", help="print JSON")
    p.set_defaults(func=_cmd_summary)

    def filters(p):
        p.add_argument("--category", help="only this category (any case)")
        p.add_argument("--since", type=_date_arg, metavar="DATE", help="from DATE, inclusive")
        p.add_argument("--until", type=_date_arg, metavar="DATE", help="up to DATE, inclusive")

    p = reader("list", "print entries, oldest first")
    filters(p)
    p.add_argument("--json", action="store_true", help="print JSON")
    p.set_defaults(func=_cmd_list)

    p = reader("export", "print entries as CSV, in list order")
    p.add_argument("--format", choices=["csv"], default="csv")
    p.set_defaults(func=_cmd_export)

    p = sub.add_parser("add", help="append an entry to a ledger file", description="append an entry")
    p.add_argument("file", metavar="FILE")
    p.add_argument("date", metavar="DATE")
    p.add_argument("category", metavar="CATEGORY")
    p.add_argument("amount", metavar="AMOUNT")
    p.add_argument("note", metavar="NOTE", nargs="?", default="")
    p.set_defaults(func=_cmd_add)
    return parser


def main(argv=None):
    """Run the command line; return the exit status."""
    try:
        args = _build_parser().parse_args(argv)
    except SystemExit as exc:
        code = exc.code
        return 0 if code is None else code
    try:
        output = args.func(args)
    except _Fail as exc:
        sys.stderr.write("pennywise: {}\n".format(exc.message))
        return exc.code
    sys.stdout.write(output)
    return 0
"""Ledger model, parser and formatting helpers."""

import datetime
import re
from dataclasses import dataclass
from decimal import Context, Decimal

_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}\Z")
_AMOUNT_RE = re.compile(r"[+-]?[0-9]+(\.[0-9]{1,2})?\Z")
_FIELD_SEP = re.compile(r"[ \t]+")
_CENT = Decimal("0.01")
_FORMAT_CONTEXT = Context(prec=1000)


class ParseError(ValueError):
    """A line of the ledger is not valid. ``line`` is its 1-based number."""

    def __init__(self, line, message):
        self.line = line
        self.reason = message
        super().__init__("line {}: {}".format(line, message))


@dataclass(frozen=True)
class Entry:
    date: datetime.date
    category: str
    amount: Decimal
    note: str = ""


def check_date(text):
    """Return the ``datetime.date`` for ``YYYY-MM-DD`` text or raise ValueError."""
    if not _DATE_RE.match(text):
        raise ValueError("invalid date {!r} (expected YYYY-MM-DD)".format(text))
    try:
        return datetime.date(int(text[0:4]), int(text[5:7]), int(text[8:10]))
    except ValueError:
        raise ValueError("invalid date {!r} (no such day)".format(text)) from None


def check_amount(text):
    """Return the Decimal for amount text or raise ValueError."""
    if not _AMOUNT_RE.match(text):
        raise ValueError(
            "invalid amount {!r} (expected a number with at most two decimals)".format(text)
        )
    return Decimal(text)


def check_category(text):
    """Return the lower-cased category or raise ValueError."""
    if not text or any(ch.isspace() for ch in text):
        raise ValueError("invalid category {!r} (expected one word)".format(text))
    return text.lower()


def parse(text):
    """Parse ledger text into a list of ``Entry`` in file order."""
    entries = []
    for number, raw in enumerate(text.split("\n"), start=1):
        line = raw.rstrip("\r").strip()
        if not line or line.startswith("#"):
            continue
        parts = _FIELD_SEP.split(line, maxsplit=3)
        if len(parts) < 3:
            raise ParseError(
                number, "expected DATE CATEGORY AMOUNT [NOTE], got {!r}".format(line)
            )
        try:
            date = check_date(parts[0])
            amount = check_amount(parts[2])
        except ValueError as exc:
            raise ParseError(number, str(exc)) from None
        note = parts[3].strip() if len(parts) == 4 else ""
        entries.append(Entry(date, parts[1].lower(), amount, note))
    return entries


def format_amount(amount):
    """Two-decimal text for an amount; never prints negative zero."""
    cents = Decimal(amount).quantize(_CENT, context=_FORMAT_CONTEXT)
    if cents.is_zero():
        cents = abs(cents)
    return format(cents, "f")


def format_entry(entry):
    """The canonical ledger line for an entry (as ``list`` prints it)."""
    line = "{} {} {}".format(entry.date.isoformat(), entry.category, format_amount(entry.amount))
    if entry.note:
        line += " " + entry.note
    return line
"""Aggregations and filtering over lists of entries."""

from decimal import Decimal


def balance(entries):
    """Total of all amounts (``Decimal(0)`` for no entries)."""
    total = Decimal(0)
    for entry in entries:
        total += entry.amount
    return total


def _totals(entries, key):
    totals = {}
    for entry in entries:
        k = key(entry)
        totals[k] = totals.get(k, Decimal(0)) + entry.amount
    return totals


def by_category(entries):
    """Dict of category -> total."""
    return _totals(entries, lambda e: e.category)


def by_month(entries):
    """Dict of ``"YYYY-MM"`` -> total."""
    return _totals(entries, lambda e: "{:04d}-{:02d}".format(e.date.year, e.date.month))


def filter_entries(entries, category=None, since=None, until=None):
    """Entries matching all given filters, in the order given.

    ``category`` ignores case; ``since`` and ``until`` are inclusive dates.
    ``None`` means no filter on that field.
    """
    wanted = category.lower() if category is not None else None
    result = []
    for entry in entries:
        if wanted is not None and entry.category.lower() != wanted:
            continue
        if since is not None and entry.date < since:
            continue
        if until is not None and entry.date > until:
            continue
        result.append(entry)
    return result

